('software-engineer', 'teknologi', 'Teknologi', 'Technology', 'Software Engineer / Programmer', 'Software Engineer / Programmer', 'Merancang, mengembangkan, dan memelihara aplikasi lunak, sistem web, dan arsitektur perangkat lunak menggunakan bahasa pemrograman modern.', 'Designs, develops, and maintains software applications, web systems, and software architecture using modern programming languages.', 8000000, 28000000, 'S1 Teknik Informatika / Sistem Informasi / Self-taught Bootcamp', 'Bachelor of Computer Science / Information Systems / Coding Bootcamp', '["JavaScript/TypeScript","React / Next.js","Python / Node.js","SQL & Database Design","Git & CI/CD","System Architecture"]'::jsonb, '["JavaScript/TypeScript","React / Next.js","Python / Node.js","SQL & Database Design","Git & CI/CD","System Architecture"]'::jsonb, 'Fleksibel (Remote / Hybrid / WFO), kantor startup atau perusahaan teknologi modern.', 'Flexible (Remote / Hybrid / WFO), startup offices or modern tech companies.', 'Junior Engineer -> Mid-Level Engineer -> Senior Engineer -> Tech Lead -> Engineering Manager / Software Architect', 'Junior Engineer -> Mid-Level Engineer -> Senior Engineer -> Tech Lead -> Engineering Manager / Software Architect', 'high', 4, 'https://images.unsplash.com/photo-1498050108023-c5249f4df085?q=80&w=800&auto=format&fit=crop', true, '[{"code":"INTJ","match_score":95,"reason_id":"Pendekatan analitis dan pemikiran sistemik sangat cocok dengan arsitektur software.","reason_en":"Analytical mindset and system architecture skills align perfectly with software engineering."},{"code":"INTP","match_score":98,"reason_id":"Suka memecahkan algoritma rumit dan bereksperimen dengan teknologi baru.","reason_en":"Loves solving complex algorithms and experimenting with novel tech stacks."},{"code":"ISTP","match_score":90,"reason_id":"Sangat terampil menggunakan alat praktis dan debugging teknis secara cepat.","reason_en":"Exceptional at using practical tools and rapid technical debugging."}]'::jsonb),
('dokter-umum', 'kesehatan', 'Kesehatan', 'Healthcare', 'Dokter Umum', 'General Practitioner / Physician', 'Melakukan pemeriksaan fisik, mendiagnosis penyakit, memberikan pengobatan dasar, serta memberikan edukasi kesehatan bagi pasien.', 'Examines physical health, diagnoses medical conditions, prescribes treatments, and promotes health education for patients.', 10000000, 35000000, 'S1 Kedokteran + Profesi Dokter (Koas) + STR Dokter', 'Bachelor of Medicine + Medical Residency + Physician License', '["Diagnosis Medis","Empati & Komunikasi Pasien","Tindakan Darurat Medis","Farmakologi","Anatomi"]'::jsonb, '["Medical Diagnosis","Patient Empathy & Communication","Emergency Procedures","Pharmacology","Anatomy"]'::jsonb, 'Rumah sakit, puskesmas, klinik swasta, dengan sistem shift kerja.', 'Hospitals, public health centers, private clinics with shift rotations.', 'Dokter PTT / Puskesmas -> Dokter Umum RS -> Dokter Spesialis -> Dokter Konsultan / Kepala Rumah Sakit', 'General Doctor -> Resident Physician -> Medical Specialist -> Hospital Consultant / Medical Director', 'high', 3, 'https://images.unsplash.com/photo-1537368910025-700350fe46c7?q=80&w=800&auto=format&fit=crop', true, '[{"code":"ISFJ","match_score":96,"reason_id":"Dedikasi tinggi, perhatian pada detail medis, dan empati hangat kepada pasien.","reason_en":"High dedication, attention to detail, and deep empathy for patients."},{"code":"ISTJ","match_score":92,"reason_id":"Sangat disiplin mengikuti protokol prosedur medis dan rekam medis akurat.","reason_en":"Disciplined in following medical protocols and maintaining accurate medical records."},{"code":"ENFJ","match_score":88,"reason_id":"Mampu menenangkan pasien dan memimpin tim perawat dengan menginspirasi.","reason_en":"Calms patients effectively and leads medical teams with inspiration."}]'::jsonb),
('ui-ux-designer', 'seni-desain', 'Seni & Desain', 'Art & Design', 'UI/UX Designer', 'UI/UX Designer', 'Riset kebutuhan pengguna dan merancang antarmuka aplikasi/website yang indah, intuitif, dan mudah digunakan.', 'Researches user needs and designs beautiful, intuitive, and highly usable app and website interfaces.', 7000000, 22000000, 'S1 Desain Komunikasi Visual (DKV) / HKI / Computer Science / Portfolio', 'Bachelor of Graphic Design / HCI / Computer Science / Portfolio-based', '["Figma / Sketch","User Research & Usability Testing","Wireframing & Prototyping","Design System","Design Thinking"]'::jsonb, '["Figma / Sketch","User Research & Usability Testing","Wireframing & Prototyping","Design System","Design Thinking"]'::jsonb, 'Studio desain, kantor teknologi, startup, atau agensi kreatif.', 'Design studios, tech firms, startups, or creative agencies.', 'Junior Designer -> UI/UX Designer -> Lead Designer -> Product Design Manager -> Head of Design', 'Junior Designer -> UI/UX Designer -> Lead Designer -> Product Design Manager -> Head of Design', 'high', 4, 'https://images.unsplash.com/photo-1581291518633-83b4ebd1d83e?q=80&w=800&auto=format&fit=crop', true, '[{"code":"INFP","match_score":94,"reason_id":"Kombinasi kreativitas estetis dan empati tinggi terhadap pengalaman pengguna.","reason_en":"Combines aesthetic creativity with deep empathy for user experience."},{"code":"ENFP","match_score":91,"reason_id":"Imajinasi tinggi dalam menciptakan konsep antarmuka yang ramah dan segar.","reason_en":"Vibrant imagination in building friendly and fresh user interface concepts."},{"code":"ISFP","match_score":89,"reason_id":"Kepekaan visual dan estetika warna yang sangat tajam.","reason_en":"Sharp visual sensibility and aesthetic eye for color composition."}]'::jsonb),
('data-scientist', 'teknologi', 'Teknologi', 'Technology', 'Data Scientist', 'Data Scientist', 'Menganalisis himpunan data besar (big data), membangun model Machine Learning, dan memberikan wawasan prediktif untuk keputusan bisnis.', 'Analyzes big data sets, builds Machine Learning models, and delivers predictive insights for strategic business decisions.', 10000000, 30000000, 'S1 Matematika / Statistika / Ilmu Komputer / Data Science', 'Bachelor of Mathematics / Statistics / Computer Science / Data Science', '["Python & R","Machine Learning & AI","SQL & BigData","Data Visualization","Statistical Analysis"]'::jsonb, '["Python & R","Machine Learning & AI","SQL & BigData","Data Visualization","Statistical Analysis"]'::jsonb, 'Kantor Korporat, FinTech, E-Commerce, konsultan data analytics.', 'Corporate offices, FinTech, E-Commerce platforms, data analytics consultancies.', 'Junior Data Analyst -> Data Scientist -> Senior Data Scientist -> Principal Data Scientist -> Head of Data', 'Junior Data Analyst -> Data Scientist -> Senior Data Scientist -> Principal Data Scientist -> Head of Data', 'high', 4, 'https://images.unsplash.com/photo-1551288049-bebda4e38f71?q=80&w=800&auto=format&fit=crop', true, '[{"code":"INTJ","match_score":97,"reason_id":"Sangat ahli dalam memodelkan pola tersembunyi dari himpunan data rumit.","reason_en":"Excels in modeling hidden patterns out of complex data sets."},{"code":"INTP","match_score":96,"reason_id":"Kreativitas analitis tinggi dalam menguji hipotesis statistik.","reason_en":"High analytical creativity in testing statistical hypotheses."},{"code":"ISTJ","match_score":88,"reason_id":"Ketelitian tinggi terhadap kebersihan data dan keakuratan angka.","reason_en":"High precision regarding data cleanliness and numerical accuracy."}]'::jsonb),
